import{frameworkTool}from"./framework-tool.js";import{defineWorkflowTool}from"#tools/workflow-definition.js";import{AGENT_ROUTER_INPUT_SCHEMA,AGENT_ROUTER_TOOL_DESCRIPTION,runAgentRouterTask}from"#execution/tools/agent-router.js";function agentRouter(){return frameworkTool(defineWorkflowTool({availableInSubagents:!1,description:AGENT_ROUTER_TOOL_DESCRIPTION,inputSchema:AGENT_ROUTER_INPUT_SCHEMA,task:runAgentRouterTask}))}export{agentRouter};